// REGISTRY 4 of 4 — every name. SEMANTIC phase.
//
// Keyed by the name exactly as the user types it. `sort` and `$sort` are two
// keys because they are two names — a JavaScript name and a MongoDB one — and
// the audit at the foot of this file makes writing either under the other's key
// a compile error. 32 such pairs exist.
//
// Four kinds share this file because they share one key space — a name — and one
// question: given this name and this receiver, in which positions is it legal
// and what MQL does each produce.
//
//   root    `$`, `$$`, `Math`      a receiver a binder can attach a name to
//   name    `sort`, `trim`, `max`  a JavaScript name
//   mongo   `$sort`, `$abs`        anything MongoDB names; "operator" and
//                                  "stage" are POSITIONS here, not kinds,
//                                  because `$count` is both
//   global  `Date`, `ObjectId`     callable by name, with no receiver
//
// 386 of these rows are generated by tmp/gen-registry.mjs from
// vendor/mql-specifications and the existing registries. Nothing is invented:
// where a fact still lives in code, the row says `pending(<file>)`.

import type {
  ArgShape,
  Arity,
  BodyRule,
  Cell,
  Emit,
  Emitter,
  ExprIn,
  Family,
  FilterIn,
  GroupIn,
  Kind,
  Lists,
  Of,
  On,
  OperandClass,
  OperatorCategory,
  Only,
  Pending,
  Position,
  QueryDoc,
  Refusal,
  Returns,
  Rule,
  Stage,
  StageIn,
  TokenName,
  ViaFallback,
} from "./vocabulary.ts";
import { Anchored, objectBody, op, pending, Range, unsupported, viaFallback } from "./vocabulary.ts";

type RootSpec<W extends readonly Position[]> = {
  doc: string;
  token: TokenName;
  /** The class a binder sees on this root's left-hand side. */
  provides: OperandClass;
  /** The receiver family a name bound to this root is resolved against. */
  family?: Family;
  where: W;
  // A root is gated like every other entry. Before these six cells existed, the
  // three context refs said `where: ["stream"]` while their only stated message
  // read "'$$' is a statement, not an aggregation expression" — one construct,
  // two registries, two answers, and nothing to catch it.
  filter: Cell<Lists<W, "filter">, Family, FilterIn, QueryDoc>;
  expr: Cell<Lists<W, "value">, Family, ExprIn, unknown>;
  stream: Cell<Lists<W, "stream">, Family, StageIn, Stage[]>;
  statement: Cell<Lists<W, "statement">, Family, StageIn, Stage[]>;
  group: Cell<Lists<W, "group">, Family, GroupIn, unknown>;
  window: Cell<Lists<W, "window">, Family, GroupIn, unknown>;
};

type NameSpec<W extends readonly Position[], O extends On> = {
  doc: string;
  /** true = called (`filter(…)`); false = read (`length`). */
  call: boolean;
  /** Probed in declaration order, so precedence is visible. */
  on: O;
  /**
   * Can it be handed to a higher-order name WITHOUT being applied?
   *   $.items.map(Math.floor)  → accepted
   *   $.items.map(Math.asinh)  → "Only the unary Math methods … can be passed as
   *                              bare callbacks"
   * Both are unary, so nothing about the arity predicts it — hence a field.
   * Absent means the name must always be called.
   */
  asReference?: boolean;
  /**
   * What a `{ … }` body on this name MEANS. Absent = "javascript", which is every
   * name but one: a stage inside such a block is refused with a rewrite hint.
   *   $$ = $$.map(d => { $sort({a:1}); });        → "takes a JavaScript callback"
   *   $$ = $$.aggregate(o => { $sort({a:1}); });  → [{ "$sort": { "a": 1 } }]
   */
  blockBody?: "javascript" | "stages";
  returns: Returns;
  where: W;
  only?: readonly Only[];
  filter: Cell<Lists<W, "filter">, Of<O>, FilterIn, QueryDoc>;
  expr: Cell<Lists<W, "value">, Of<O>, ExprIn, unknown>;
  /** A link in a `$$ = $$…` chain. */
  stream: Cell<Lists<W, "stream">, Of<O>, StageIn, Stage[]>;
  /** A `;`-separated statement. SEPARATE from `stream` — see Position. */
  statement: Cell<Lists<W, "statement">, Of<O>, StageIn, Stage[]>;
  group: Cell<Lists<W, "group">, Of<O>, GroupIn, unknown>;
  /** $setWindowFields.output — a DIFFERENT slot from $group. See MongoSpec.window. */
  window: Cell<Lists<W, "window">, Of<O>, GroupIn, unknown>;
};

type MongoSpec<
  W extends readonly Position[],
  F extends readonly string[] = readonly string[],
  I extends Readonly<Partial<Record<Position, readonly string[]>>> = Readonly<Record<never, never>>,
> = {
  /**
   * Lifted from vendor/mql-specifications; the drift test compares it. A name that is
   * BOTH an operator and a stage ($count) has two descriptions, and one string cannot
   * hold both — so those rows state each against its role.
   */
  doc: string | { operator: string; stage: string };
  /**
   * From OPERATOR_CATEGORIES. Absent for a name that is only ever a stage —
   * MongoDB categorises its operators, not its stages.
   */
  category?: OperatorCategory;
  where: W;
  only?: readonly Only[];
  /**
   * How the operand list is written, for the expression positions. Omitted for
   * a name that is only ever a stage: its `body` is its shape.
   */
  shape?: "single" | "array" | "none" | "flex" | { object: BodyRule };
  /** Stage-position facts. Meaningful when `where` includes "stream". */
  body?: BodyRule | Pending;
  /**
   * DOTTED PATHS to the body fields that hold a nested pipeline. A `*` segment
   * means "every key of this object". A flat key list could not reach
   * $rankFusion's, which sit one level down and are user-named:
   *   $lookup      → ["pipeline"]
   *   $merge       → ["whenMatched"]          only when it is not a keyword
   *   $rankFusion  → ["input.pipelines.*"]
   */
  subPipelineFields?: readonly string[];
  /** See MongoOpParts.minVersion. */
  minVersion?: string;
  /**
   * true when this stage REPLACES the document, so nothing carried in a field
   * survives it. MEASURED — the six that do, and the near neighbours that do not:
   *   let t = $.a; $group({_id:$.k}); $.b = t   → "`t` … can't be read after '$group'"
   *   let t = $.a; $project({a:1});   $.b = t   → compiles
   *   let t = $.a; $sort({a:1});      $.b = t   → compiles
   * Three separate consumers need it: the scope tracker that drops `let`
   * bindings, the peephole that skips the trailing namespace cleanup, and the
   * stream-chain form. It was six hardcoded strings in src/pipeline.ts, so all
   * three read a set no row declared.
   */
  replacesDocument?: true;
  /** Containers this may not appear inside — by registry KEY, dollar included. */
  forbiddenIn?: F;
  /**
   * The operators whose BODY accepts this name, PER POSITION. A name listed here
   * is never valid on its own in that position — measured both ways:
   *   { loc: { $geoWithin: { $box: [[-1,-1],[1,1]] } } }   accepted
   *   { $addFields: { v: { $box: [[0,0],[1,1]] } } }       "Unrecognized expression '$box'"
   *
   * Per position because the two are independent. `$slice` stands alone as an
   * aggregation operator AND appears inside `$push` in an update document, so a
   * flat list would constrain the standalone use as well:
   *   $slice: onlyInside: { updateDoc: ["$push"] }
   * The nesting does not change `where` — `$box` is still reached in a filter,
   * `$each` in an update document, `$case` in a value.
   */
  onlyInside?: I;
  filter: Cell<Lists<W, "filter">, Family, FilterIn, QueryDoc>;
  expr: Cell<Lists<W, "value">, Family, ExprIn, unknown>;
  group: Cell<Lists<W, "group">, Family, GroupIn, unknown>;
  /**
   * $setWindowFields.output is a DIFFERENT slot from $group, proven both ways on mongod:
   * $rank is a window function and not a group operator; $mergeObjects the reverse.
   */
  window: Cell<Lists<W, "window">, Family, GroupIn, unknown>;
  /** A link in a `$$ = $$…` chain. */
  stream: Cell<Lists<W, "stream">, Family, StageIn, Stage[]>;
  /**
   * A top-level `;`-separated statement. SEPARATE from `stream`: `$match(…);`
   * and `$$ = $$.$match(…)` are both legal and a stage row must be able to say
   * so, while `$$.push(...)` is a statement whose chain-link form is refused.
   */
  statement: Cell<Lists<W, "statement">, Family, StageIn, Stage[]>;
  /**
   * The update DOCUMENT — `updateOne(filter, { $inc: … })`. A whole operator
   * family is valid only here and nowhere else in MQL: the same document in a
   * pipeline is "Unrecognized pipeline stage name: '$inc'".
   */
  updateDoc: Cell<Lists<W, "updateDoc">, Family, GroupIn, unknown>;
};

type GlobalSpec<W extends readonly Position[]> = {
  doc: string;
  token: TokenName;
  /** `new` before it. `ObjectId` takes both spellings; `Set` demands it. */
  newKeyword: "required" | "optional" | "forbidden";
  /** Can it be handed to a higher-order name unapplied — `map(String)`? */
  asReference: boolean;
  /** When it is also a namespace: the family a name bound to it resolves against. */
  provides?: Family;
  returns: Returns;
  where: W;
  only?: readonly Only[];
  filter: Cell<Lists<W, "filter">, Family, FilterIn, QueryDoc>;
  expr: Cell<Lists<W, "value">, Family, ExprIn, unknown>;
  // `assert(cond);` is receiver-less AND statement-only. With only the two cells
  // above, it had nowhere to be written at all.
  stream: Cell<Lists<W, "stream">, Family, StageIn, Stage[]>;
  statement: Cell<Lists<W, "statement">, Family, StageIn, Stage[]>;
  group: Cell<Lists<W, "group">, Family, GroupIn, unknown>;
  window: Cell<Lists<W, "window">, Family, GroupIn, unknown>;
};

export type RootEntry<W extends readonly Position[]> = RootSpec<W> & { kind: "root" };
export type NameEntry<W extends readonly Position[], O extends On> = NameSpec<W, O> & { kind: "name" };
export type MongoEntry<
  W extends readonly Position[],
  F extends readonly string[] = readonly never[],
  I extends Readonly<Partial<Record<Position, readonly string[]>>> = Readonly<Record<never, never>>,
> = MongoSpec<W, F, I> & { kind: "mongo" };
export type GlobalEntry<W extends readonly Position[]> = GlobalSpec<W> & { kind: "global" };

// Every generic defaults to the EMPTY type, never to its constraint — a row with
// no `forbiddenIn` would otherwise widen `F` to `readonly string[]` and the
// audit below would pass while checking nothing.
const root = <const W extends readonly Position[]>(e: RootSpec<W>): RootEntry<W> => ({ ...e, kind: "root" });
const name = <const W extends readonly Position[], const O extends On>(e: NameSpec<W, O>): NameEntry<W, O> => ({
  ...e,
  kind: "name",
});
const mongo = <
  const W extends readonly Position[],
  const F extends readonly string[] = readonly never[],
  const I extends Readonly<Partial<Record<Position, readonly string[]>>> = Readonly<Record<never, never>>,
>(
  e: MongoSpec<W, F, I>,
): MongoEntry<W, F, I> => ({ ...e, kind: "mongo" });
const global_ = <const W extends readonly Position[]>(e: GlobalSpec<W>): GlobalEntry<W> => ({ ...e, kind: "global" });

